    verify(databaseMeta, times(0)).supportsAutoGeneratedKeys();
    dimensionLookupSpy.dimInsert(iRowMeta, objects, null, true, null, date, date);
    verify(databaseMeta, times(2)).supportsAutoGeneratedKeys();
}

