    assertEquals(kerberosAuthenticationProvider.isUseKeytab(), captor.getValue().isUseKeytab());
    assertEquals(kerberosAuthenticationProvider.isUseExternalCredentials(), captor.getValue().isUseExternalCredentials());
}

