    // "\\valueA"|"valueB\\"|"val\\ueC"
    String line = "\"\\\\valueA\"|\"valueB\\\\\"|\"val\\\\ueC\"";
    String[] strings = TextFileInputUtils.guessStringsFromLine(Mockito.mock(IVariables.class), Mockito.mock(ILogChannel.class), line, inputMeta, "|", "\"", "\\");
