                when(bufferedReader.readLine()).thenReturn(UBUNTU_16_NAME);
                break;
            case UBUNTU_14:
                when(bufferedReader.readLine()).thenReturn(UBUNTU_14_NAME);
                break;
            case UBUNTU_WRONG:
                when(bufferedReader.readLine()).thenReturn(UBUNTU_16_NAME);
